bad.agent/gate.py:
"""Park a sensitive tool call for a person, then carry on when they answer."""

from langgraph.types import interrupt

PENDING_APPROVAL = {}


def gate(tool_call, thread_id):
    """Hold this thread until somebody answers."""
    PENDING_APPROVAL[thread_id] = {"tool": tool_call.name, "args": tool_call.args}
    answer = interrupt({"tool": tool_call.name, "args": tool_call.args})
    PENDING_APPROVAL.pop(thread_id, None)
    if answer == "approve":
        return tool_call.run()
    return {"status": "rejected"}

bad.worker/queue.py:
"""Items a person has to look at before the agent may proceed."""

REVIEW_QUEUE = []


def enqueue_for_review(item, now):
    REVIEW_QUEUE.append({"item": item, "created_at": now})


def next_for_reviewer():
    return REVIEW_QUEUE.pop(0) if REVIEW_QUEUE else None


def queue_depth():
    return len(REVIEW_QUEUE)

good.agent/gate.py:
"""Park a sensitive tool call for a person, then carry on when they answer.

A parked call is not allowed to sit forever: it carries a deadline, and the
sweeper escalates it to a second person and then refuses it if nobody answers.
"""

from langgraph.types import interrupt

APPROVAL_DEADLINE_SECONDS = 3600
PENDING_APPROVAL = {}


def gate(tool_call, thread_id, now):
    PENDING_APPROVAL[thread_id] = {
        "tool": tool_call.name,
        "args": tool_call.args,
        "created_at": now,
        "expires_at": now + APPROVAL_DEADLINE_SECONDS,
    }
    answer = interrupt({
        "tool": tool_call.name,
        "args": tool_call.args,
        "answer_by": now + APPROVAL_DEADLINE_SECONDS,
    })
    PENDING_APPROVAL.pop(thread_id, None)
    if answer == "approve":
        return tool_call.run()
    return {"status": "rejected"}

good.worker/sweeper.py:
"""Age out, escalate and alarm on decisions nobody has answered.

An unanswered request is a signal, not a resting state. Expiry refuses the call
rather than allowing it, because a deadline that defaults to yes is not a gate.
"""

ESCALATE_AFTER_SECONDS = 1800


def sweep(queue, now, refuse, escalate_to, secondary_reviewer):
    for item in list(queue):
        waited = now - item["created_at"]
        if now >= item["expires_at"]:
            item["state"] = "aged_out"
            refuse(item, reason="approval deadline passed with no human decision")
            queue.remove(item)
        elif waited > ESCALATE_AFTER_SECONDS and not item.get("escalated"):
            escalate_to(secondary_reviewer(item), item)
            item["escalated"] = True


def oldest_pending_age(queue, now):
    """Exported so a dashboard can alarm on a review queue nobody is reading."""
    return max((now - i["created_at"] for i in queue), default=0)
